* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: 1rem 0;
    margin-bottom: 2rem;
}

header h1 {
    font-size: 1.5rem;
    font-weight: 700;
}

main {
    flex: 1;
}

.image-card {
    background-color: var(--color-surface);
    border-radius: var(--radius);
    overflow: hidden;
    box-shadow: var(--shadow);
}

.image-wrapper {
    aspect-ratio: 4 / 3;
    background-color: #eee;
}

.image-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.image-actions {
    padding: 1.5rem;
    display: flex;
    justify-content: center;
}

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: var(--radius);
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s;
    border: none;
    font-family: inherit;
}

.btn:focus-visible {
    outline: 2px solid transparent;
    box-shadow: 0 0 0 3px var(--color-focus);
}

.btn-danger {
    background-color: var(--color-danger);
    color: white;
}

.btn-danger:hover {
    background-color: var(--color-danger-hover);
}

.btn-secondary {
    background-color: var(--color-secondary);
    color: white;
}

.btn-secondary:hover {
    background-color: var(--color-secondary-hover);
}

footer {
    padding: 2rem 0;
    text-align: center;
    color: var(--color-text-muted);
    font-size: 0.875rem;
}

/* Dialog Styles */
dialog {
    border: none;
    border-radius: var(--radius);
    padding: 0;
    box-shadow: var(--shadow-lg);
    max-width: 90%;
    width: 400px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    margin: 0; /* Important for positioning */
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(2px);
}

.dialog-content {
    padding: 2rem;
}

.dialog-content h2 {
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.dialog-content p {
    color: var(--color-text-muted);
    margin-bottom: 2rem;
}

.dialog-footer {
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

@media (forced-colors: active) {
    dialog {
        border: 2px solid ButtonBorder;
    }
    .btn:focus-visible {
        outline: 2px solid ButtonText;
    }
}

@media (max-width: 480px) {
    .dialog-footer {
        flex-direction: column;
    }
    .btn {
        width: 100%;
    }
}
