', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s0/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-confirm');
    const trigger = document.querySelector('.trigger');
    const cancelBtn = document.getElementById('cancel-btn');
    const confirmBtn = document.getElementById('confirm-btn');

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
    });

    // Close on cancel
    cancelBtn.addEventListener('click', () => {
        dialog.close();
    });

    // Action on confirm
    confirmBtn.addEventListener('click', () => {
        const statusRegion = document.getElementById('status-region');
        statusRegion.textContent = 'Image deleted successfully.';

        dialog.close();

        // Visual feedback for the demo
        const imageCard = document.querySelector('.image-card');
        imageCard.style.opacity = '0.5';
        imageCard.innerHTML = '<div style="padding: 2rem; text-align: center;" aria-hidden="true">Image deleted from library.</div>';
    });

    // Close when clicking on the backdrop
    dialog.addEventListener('click', (event) => {
        if (event.target === dialog) {
            dialog.close();
        }
    });
});
