             <h1>Photo Library</h1>
         </div>
     </header>

     <main>
         <div class="container">
             <div class="image-card">
                 <div class="image-wrapper">
                     <img src="https://picsum.photos/800/600" alt="Beautiful landscape with mountains and a lake at sunset">
                 </div>
                 <div class="image-actions">
                     <button type="button" class="trigger btn btn-danger">
                         Delete Image
                     </button>
                 </div>
             </div>
         </div>
     </main>

     <footer>
         <div class="container">
             <p>&copy; 2024 Photo Library. All rights reserved.</p>
         </div>
     </footer>

     <dialog id="delete-confirm" role="alertdialog" aria-labelledby="dialog-title" aria-describedby="dialog-desc">
         <div class="dialog-content">
             <h2 id="dialog-title">Delete this image?</h2>
             <p id="dialog-desc">Are you sure you want to delete this image from your library? This action cannot be undone.</p>
             <div class="dialog-footer">
                 <button type="button" class="btn btn-secondary" id="cancel-btn">Cancel</button>
                 <button type="button" class="btn btn-danger" id="confirm-btn">Yes, Delete</button>
             </div>
         </div>
     </dialog>

     <div id="status-region" role="status" aria-live="polite" class="sr-only"></div>

     <script>
         document.addEventListener('DOMContentLoaded', () => {
             const dialog = document.getElementById('delete-confirm');
             const trigger = document.querySelector('.trigger');
             const cancelBtn = document.getElementById('cancel-btn');
             const confirmBtn = document.getElementById('confirm-btn');

             // Open dialog
             trigger.addEventListener('click', () => {
                 dialog.showModal();
             });

             // Close on cancel
             cancelBtn.addEventListener('click', () => {
                 dialog.close();
             });

             // Action on confirm
             confirmBtn.addEventListener('click', () => {
                 const statusRegion = document.getElementById('status-region');
                 statusRegion.textContent = 'Image deleted successfully.';

                 dialog.close();

                 // Visual feedback for the demo
                 const imageCard = document.querySelector('.image-card');
                 imageCard.style.opacity = '0.5';
                 imageCard.innerHTML = '<div style="padding: 2rem; text-align: center;" aria-hidden="true">Image deleted from library.</div>';
             });

             // Close when clicking on the backdrop
             dialog.addEventListener('click', (event) => {
                 if (event.target === dialog) {
                     dialog.close();
                 }
             });
         });
     </script>
 </body>
 </html>

')
